import { expect, test } from "bun:test";

class MailerDouble implements Mailer {
	sent: string[] = [];

	send(to: string): void {
		this.sent.push(to);
	}
}

test("notifies the buyer", () => {
	const mailer = new MailerDouble();
	checkout(order, mailer);
	expect(mailer.sent).toEqual(["ana@example.test"]);
});

