import { expect, mock, test } from "bun:test";

test("applies the discount", () => {
	const pricing = {
		subtotal: mock(() => 100),
		discount: mock(() => 10),
	};

	priceOrder(order, pricing);

	expect(pricing.subtotal).toHaveBeenCalledTimes(1);
	expect(pricing.discount).toHaveBeenCalledTimes(1);
});

